function badge(s){let k=String(s||'');let color=/REFUS|REJET|ANNULE/.test(k)?'red':/APPROUV|RETEN|VALIDE|SIGNE|REALISE|TERMINE|ACCEPTEE|PUBLIEE|TRANSMISE|POSTE_CREE|OUI/.test(k)?'green':/ATTENTE|A_CORRIGER|PLANIF|EN_COURS|PRESELECTION|ENTRETIEN/.test(k)?'orange':'gray';return `<span class="badge ${color}">${E(displayStatus[k]||k.replaceAll('_',' '))}</span>`}
