function toast(msg,type=''){let host=document.getElementById('toast-root');let el=document.createElement('div');el.className='toast '+type;el.textContent=msg;host.append(el);setTimeout(()=>el.remove(),4400)}
function needRole(...roles){if(!roles.includes(session?.role)){toast('Action réservée à : '+roles.map(r=>PROFILES[r]?.label).join(', '),'error');return false}return true}
function actButton(action,label,variant='white',id='',extra=''){return `<button type="button" class="btn btn-${variant}" data-action="${attr(action)}" ${id!==''?`data-id="${attr(id)}"`:''} ${extra}>${label}</button>`}
function navButton(screen,label,variant='white',id='',extra=''){return `<button type="button" class="btn btn-${variant}" data-nav="${attr(screen)}" ${id!==''?`data-id="${attr(id)}"`:''} ${extra}>${label}</button>`}
const smallNav=(name,id,label='Ouvrir')=>navButton(name,E(label),'secondary',id,'style="min-height:30px;padding:5px 9px"');
function formField(name,label,type='text',value='',opts={}){const mandatory=opts.required?' required':'';const placeholder=opts.placeholder?` placeholder="${attr(opts.placeholder)}"`:'';const readonly=opts.readonly?' readonly':'';let control;if(opts.options){control=`<select name="${name}" id="f-${name}" ${mandatory} ${opts.disabled?'disabled':''}>${opts.options.map(v=>{let [id,l]=Array.isArray(v)?v:[v,displayStatus[v]||v];return `<option value="${attr(id)}" ${String(id)===String(value)?'selected':''}>${E(l)}</option>`}).join('')}</select>`}else if(type==='textarea'){control=`<textarea name="${name}" id="f-${name}" ${mandatory}${placeholder}${readonly}>${E(value)}</textarea>`}else{control=`<input type="${type}" name="${name}" id="f-${name}" value="${attr(value??'')}" ${mandatory}${placeholder}${readonly} ${opts.min!==undefined?`min="${attr(opts.min)}"`:''} ${opts.max!==undefined?`max="${attr(opts.max)}"`:''} ${opts.step!==undefined?`step="${attr(opts.step)}"`:''}>`};return `<div class="field ${opts.full?'full':''}"><label for="f-${name}">${E(label)}${opts.required?' *':''}</label>${control}${opts.hint?`<small>${E(opts.hint)}</small>`:''}</div>`}
function optList(key,labelKey='name',prefix=null){return db[key].map(x=>[x.id,(prefix||'')+x[labelKey]])}
const panel=(title,content,sub='',actions='')=>`<section class="panel"><div class="panel-head"><div><h2 class="panel-title">${title}</h2>${sub?`<p class="panel-sub">${sub}</p>`:''}</div>${actions}</div><div class="panel-body">${content}</div></section>`;
function page(title,subtitle='',actions='',content='',eyebrow='ESPACE DE TRAVAIL'){return `<div class="page-head"><div><div class="eyebrow">${E(eyebrow)}</div><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div><div class="action-row">${actions}</div></div>${content}`}
function details(items){return `<dl class="detail-grid">${items.map(([k,v])=>`<div class="detail"><dt>${E(k)}</dt><dd>${v??'—'}</dd></div>`).join('')}</dl>`}
function dataTable(columns,rows,tableId='default'){let q=ui.search.trim().toLowerCase(),f=ui.filter;let r=rows.filter(row=>(!q||((row.search||row.cols.join(' ')).toLowerCase().includes(q)))&&(!f||String(row.status||'')===f));if(ui.sort!==null){let c=ui.sort; r=[...r].sort((a,b)=>String(a.cols[c]??'').localeCompare(String(b.cols[c]??''),'fr',{numeric:true})*(ui.sortDesc?-1:1))}const pageSize=8, max=Math.max(1,Math.ceil(r.length/pageSize));ui.page=Math.min(ui.page,max);let shown=r.slice((ui.page-1)*pageSize,ui.page*pageSize);return `<div class="table-wrap"><table><thead><tr>${columns.map((s,i)=>`<th><button type="button" style="font:inherit;letter-spacing:inherit;text-transform:inherit;border:0;background:none;padding:0;color:inherit;cursor:pointer" data-sort="${i}">${E(s)} ${ui.sort===i?(ui.sortDesc?'↓':'↑'):''}</button></th>`).join('')}</tr></thead><tbody>${shown.length?shown.map(row=>`<tr>${row.cols.map((val)=>`<td>${val??'—'}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${columns.length}"><div class="empty"><span class="big">⌕</span>Aucun résultat pour ces critères.</div></td></tr>`}</tbody></table></div><div class="pagination"><span class="table-info" style="margin-right:auto">${r.length} résultat(s)</span><button data-page="prev" ${ui.page===1?'disabled':''}>‹</button><span class="small muted">${ui.page} / ${max}</span><button data-page="next" ${ui.page>=max?'disabled':''}>›</button></div>`}
function filters(statuses=[],placeholder='Rechercher...',extra=''){return `<div class="toolbar"><input type="search" id="list-search" data-search placeholder="${attr(placeholder)}" value="${attr(ui.search)}" aria-label="Rechercher"><select data-filter aria-label="Filtrer par statut"><option value="">Tous les statuts</option>${statuses.map(v=>`<option value="${attr(v)}" ${ui.filter===v?'selected':''}>${E(displayStatus[v]||v)}</option>`).join('')}</select>${extra}</div>`}
function ask(title,message,callback,destructive=false){ui.modal={title,message,callback,destructive};renderModal()}
function renderModal(){let root=document.getElementById('modal-root');if(!ui.modal){root.innerHTML='';return}root.innerHTML=`<div class="modal-backdrop" data-modal-bg><div class="modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header><h2 id="dialog-title">${E(ui.modal.title)}</h2><button class="icon-btn" data-action="close-modal" aria-label="Fermer">×</button></header><div class="body"><p>${E(ui.modal.message)}</p><label for="modal-comment" class="small strong">Commentaire ou motif (selon l'action)</label><textarea id="modal-comment" placeholder="Commentaire…" rows="3"></textarea></div><footer>${actButton('close-modal','Annuler')}${actButton('modal-confirm','Confirmer',ui.modal.destructive?'danger':'primary')}</footer></div></div>`;root.querySelector('#modal-comment')?.focus()}
