const allowed=(screen,role=session?.role)=>!!role&&menuAccess[role]?.includes(screen);
function nav(screen,id){if(!allowed(screen)){toast('Cet écran n’est pas disponible pour ce rôle de démonstration.','error');return}ui.screen=screen;ui.ctx=id!==''&&id!==undefined?{id:Number(id)}:{};ui.search='';ui.filter='';ui.sort=null;ui.sortDesc=false;ui.contractType='';ui.editInterview=null;ui.page=1;ui.mobile=false;history.replaceState(null,'','#'+screen+(ui.ctx.id?'/'+ui.ctx.id:''));render();window.scrollTo(0,0)}
function loginHTML(){return `<div class="login-screen"><section class="login-hero"><div><div class="brand-mark">N</div><div style="margin-top:60px"><span class="demo-tag">SIRH · VERSION DÉMONSTRATION</span><h1 style="margin-top:18px">Les ressources humaines, avec clarté.</h1><p>Du besoin initial à l'intégration du salarié, explorez une expérience de gestion RH fluide, organisée et cohérente.</p></div></div><div class="login-badges"><span class="demo-tag">04 blocs connectés</span><span class="demo-tag">06 profils métier</span><span class="demo-tag">100 % frontend</span></div></section><section class="login-side"><div class="login-card"><div class="eyebrow">Bienvenue sur NovaRH</div><h2>Connexion de démonstration</h2><p class="muted" style="margin-top:9px">Aucun compte réel n'est utilisé. Choisissez un rôle pour tester les écrans.</p><form data-form="login"><div class="field"><label for="login-role">Profil de démonstration *</label><select name="role" id="login-role" required>${Object.entries(PROFILES).map(([k,v])=>`<option value="${k}">${E(v.label)} — ${E(v.name)}</option>`).join('')}</select></div><div class="field"><label for="login-user">Identifiant de démonstration *</label><input id="login-user" name="login" value="demo" required autocomplete="off"></div><div class="field"><label for="login-pass">Mot de passe de démonstration *</label><div class="field-inline"><input id="login-pass" type="password" name="password" value="demo" required autocomplete="off"><button class="icon-btn" type="button" data-action="toggle-password" aria-label="Afficher le mot de passe">◉</button></div></div><button class="btn btn-primary" type="submit">Accéder à l'espace RH →</button></form><div class="notice" style="margin-top:22px">Simulation visuelle uniquement. Les rôles ne constituent pas une sécurité serveur. Vos changements restent locaux à ce navigateur.</div><p class="small muted">Utiliser <b>demo / demo</b> uniquement pour ce prototype.</p></div></section></div>`}
function renderShell(){const role=session.role,p=PROFILES[role],menu=categories.map(cat=>{let links=cat.links.filter(([id])=>allowed(id));if(!links.length)return '';let open=ui.groups[cat.name]!==false;return `<div class="nav-group"><button class="nav-heading" data-group="${attr(cat.name)}" title="Déplier ou replier"><span>${E(cat.name)}</span><span>${open?'⌄':'›'}</span></button>${open?links.map(([id,label,icon])=>`<button class="nav-link ${ui.screen===id?'active':''}" data-nav="${id}" title="${attr(label)}"><span class="nav-ic">${icon}</span><span class="nav-label">${E(label)}</span></button>`).join(''):''}</div>`}).join('');let label=categories.flatMap(g=>g.links).find(x=>x[0]===ui.screen)?.[1]||'Tableau de bord';return `<div class="mobile-mask ${ui.mobile?'show':''}" data-action="mobile-close"></div><div class="app-layout ${ui.collapsed?'compact':''}"><aside class="sidebar ${ui.mobile?'mobile-open':''}"><div class="brand"><div class="brand-mark">N</div><div><div class="brand-name">NovaRH</div><small>Gestion des talents</small></div></div>${menu}<div class="nav-foot">● Mode démonstration<br>Aucune donnée serveur.</div></aside><div class="main-area"><header class="topbar"><div class="top-left"><button class="icon-btn mobile-toggle" data-action="mobile-toggle" aria-label="Ouvrir le menu">☰</button><button class="icon-btn" data-action="collapse" aria-label="Réduire le menu">☷</button><div class="breadcrumb">Espace RH / <strong>${E(label)}</strong></div></div><div class="top-right"><span class="badge blue">DÉMO</span><select class="role-switch" data-role aria-label="Changer de rôle">${Object.entries(PROFILES).map(([k,v])=>`<option value="${k}" ${k===role?'selected':''}>${E(v.label)}</option>`).join('')}</select><div class="avatar">${p.initials}</div><div><div class="profile-title">${E(p.name)}</div><div class="profile-sub">${E(p.label)}</div></div><button class="icon-btn" data-action="logout" title="Déconnexion">↪</button></div></header><main class="workspace" id="main-content">${renderScreen()}</main></div></div>`}
function render(){document.getElementById('app').innerHTML=session?renderShell():loginHTML();renderModal()}
function renderScreen(){if(!allowed(ui.screen))ui.screen='dashboard';try{return screenHandlers[ui.screen]?.()||page('Écran indisponible','','',`<div class="notice warn">Cette page n’existe pas dans le prototype.</div>`)}catch(err){console.error(err);return page('Erreur d’affichage','Une vue a rencontré une erreur de démonstration.',actButton('reset','Réinitialiser les données','danger'),`<pre>${E(err.message)}</pre>`)}}
function dashboard(){let role=session.role, shortcuts=categories.flatMap(g=>g.links).filter(x=>allowed(x[0])&&x[0]!=='dashboard'&&!(x[0].includes('form')||x[0].includes('detail'))).slice(0,6);
 const nums=[['Demandes actives',db.requests.filter(r=>!['REFUSEE','APPROUVEE'].includes(r.status)).length,'◫'],['Offres publiées',db.offers.filter(o=>o.status==='PUBLIEE').length,'▤'],['Candidatures',db.applications.length,'♙'],['Onboarding à suivre',db.onboardings.filter(o=>o.tasks.some(t=>t.status!=='TERMINE')).length,'◴']];
 return page('Bonjour, '+E(PROFILES[role].name.split(' ')[0])+' 👋','Vue synthétique du cycle RH, adaptée au profil de démonstration.',actButton('reset','Réinitialiser la démo','white'),`<div class="notice"><b>Prototype frontend :</b> les indicateurs, formulaires et opérations proviennent d'un jeu de données local. Aucune transmission à une entreprise ou un serveur.</div><div class="cards">${nums.map(([l,n,i])=>`<div class="stat"><div class="stat-ico">${i}</div><div class="num">${n}</div><div class="label">${l}</div><div class="hint">Données de démonstration</div></div>`).join('')}</div><div class="split">${panel('Accès rapides',`<div class="grid3">${shortcuts.map(([id,name,icon])=>`<button class="shortcut" data-nav="${id}"><div class="ico">${icon}</div><div class="txt">${E(name)}</div><div class="sub">Ouvrir le module →</div></button>`).join('')}</div>`,'Fonctions disponibles selon votre rôle')}${panel('Activité récente',`<div class="timeline">${db.log.slice(0,6).map(l=>`<div class="timeline-item"><b class="small">${E(l.action.replaceAll('_',' '))}</b><div class="date">${E(l.by)} • ${datetime(l.date)}</div><div class="small muted">${E(l.module.replaceAll('_',' '))} · ${E(l.entity)} #${l.entityId}</div></div>`).join('')}</div>`,'Historique simulé')}</div><div class="grid2">${panel('Du besoin à l’embauche',`<p class="muted">Besoin → Examen hiérarchique → RH → Finance si requise → Direction → Poste → Offre → Candidature → Évaluation → Proposition → Validation → Dossier salarié.</p>`)}${panel('Règles essentielles',`<p class="muted">Une offre exige une demande approuvée. Une candidature retenue ne crée pas de salarié. L'embauche exige une réponse acceptée et une validation de la Direction. Six tâches fixes suivent la signature.</p>`)}</div>`,'ACCUEIL')}
function requestSummary(r){return details([['Référence','D-'+String(r.id).padStart(3,'0')],['Demandeur',E(who(r.author))],['Département',E(dept(r.dept))],['Intitulé proposé',E(r.jobTitle)],['Motif',E(r.motif)],['Budget minimum',E(money(r.min))],['Budget maximum',E(money(r.max))],['Finance requise',r.financeRequired?'Oui':'Non'],['État',badge(r.status)]])}
function requestsScreen(){const arr=session.role==='manager'?db.requests.filter(r=>r.author===1):db.requests;let rows=arr.map(r=>({status:r.status,search:[r.jobTitle,r.motif,dept(r.dept),r.status].join(' '),cols:[`D-${String(r.id).padStart(3,'0')}`,`<b>${E(r.jobTitle)}</b><div class="subline">${E(r.motif.slice(0,55))}</div>`,E(dept(r.dept)),date(r.created),badge(r.status),`<div class="table-actions">${smallNav('request-check',r.id,'Consulter')}${session.role==='manager'&&['BROUILLON','A_CORRIGER'].includes(r.status)?smallNav('request-form',r.id,'Modifier'):''}</div>`]}));return page('Demandes de personnel','Suivez les besoins, les validations et les retours des responsables.',session.role==='manager'?navButton('request-form','＋ Nouvelle demande','primary'):'',panel('Liste des demandes',filters(['BROUILLON','ATTENTE_HIERARCHIE','ATTENTE_RH','ATTENTE_FINANCE','ATTENTE_DIRECTION','APPROUVEE','REFUSEE','A_CORRIGER'],'Motif, département, poste…')+dataTable(['Référence','Besoin','Département','Date','Statut','Actions'],rows)), 'BLOC 1 · EXPRESSION DU BESOIN')}
function requestForm(){if(!needRole('manager'))return '';let r=find('requests',ui.ctx.id);if(r&&!['BROUILLON','A_CORRIGER'].includes(r.status))return page('Modification bloquée','Seuls les brouillons et les dossiers retournés sont modifiables.',navButton('requests','Retour'));return page(r?'Modifier la demande':'Nouvelle demande','Exprimez un besoin en personnel avant le circuit d’examen.',navButton('requests','← Liste'),panel('Informations de la demande',`<form data-form="request"><div class="form-grid">${formField('dept','Département','select',r?.dept||1,{required:true,options:optList('departments')})}${formField('jobTitle','Intitulé du poste souhaité','text',r?.jobTitle||'',{required:true,hint:'Champ d’interface provisoire : à ajouter au modèle du Bloc 1.'})}${formField('motif','Motif et justification','textarea',r?.motif||'',{required:true,full:true})}${formField('description','Description du poste','textarea',r?.description||'',{full:true})}${formField('skills','Compétences nécessaires','textarea',r?.skills||'',{full:true})}${formField('min','Budget minimum (Ar)','number',r?.min??'',{min:0,hint:'Facultatif'})}${formField('max','Budget maximum (Ar)','number',r?.max??'',{min:0,hint:'Facultatif'})}</div><div class="form-actions"><button class="btn btn-primary" type="submit">Enregistrer en brouillon</button>${navButton('requests','Annuler')}</div></form>`,'Le budget peut être complété ensuite par RH.')+`<div class="notice warn">Le document Bloc 1 ne définit pas encore de stockage SQL pour l’intitulé et les compétences avant création du poste. Ces valeurs sont uniquement simulées dans cette démo.</div>`,'BLOC 1')}
function requestCheck(){let r=find('requests',ui.ctx.id)||db.requests[0];if(!r)return page('Demande introuvable');return page('Demande D-'+String(r.id).padStart(3,'0'),'Vérification, décision et historique du dossier.',navButton('requests','← Mes demandes'),panel('Résumé du besoin',requestSummary(r),'Informations courantes',`<div class="action-row">${session.role==='manager'&&['BROUILLON','A_CORRIGER'].includes(r.status)?navButton('request-form','Modifier','white',r.id)+actButton('request-submit','Soumettre au responsable','primary',r.id):''}</div>`)+historyPanel('BLOC_1','DEMANDE',r.id),'BLOC 1')}
function queuePage(config){let arr=db.requests.filter(r=>r.status===config.status);let r=ui.ctx.id?find('requests',ui.ctx.id):null;if(r?.status!==config.status)r=null;let list=panel('Dossiers à traiter',dataTable(['Référence','Besoin','Département','Statut','Action'],arr.map(x=>({status:x.status,cols:[`D-${x.id}`,E(x.jobTitle),E(dept(x.dept)),badge(x.status),smallNav(config.screen,x.id,'Examiner')]}))),'Sélectionnez un dossier pour formuler votre décision.');let detail=r?panel('Examen du dossier D-'+r.id,requestSummary(r)+config.form(r),'', ''):'';return page(config.title,config.sub,'',list+detail,'BLOC 1 · CIRCUIT DE VALIDATION')}
function hierarchyScreen(){return queuePage({screen:'hierarchy',status:'ATTENTE_HIERARCHIE',title:'Examen hiérarchique',sub:'Approuver, refuser ou retourner les demandes du périmètre.',form:r=>`<form data-form="hierarchy"><div class="form-grid">${formField('decision','Décision','select','APPROUVER',{required:true,options:[['APPROUVER','Approuver et transmettre aux RH'],['RETOUR','Retourner pour correction'],['REFUSER','Refuser']]})}${formField('comment','Commentaire / motif','textarea','',{full:true})}</div><div class="form-actions"><button class="btn btn-primary">Enregistrer la décision</button></div></form>`})}
function rhReviewScreen(){return queuePage({screen:'rh-review',status:'ATTENTE_RH',title:'Analyse RH',sub:'Contrôlez le besoin, ajustez le budget et déterminez la suite.',form:r=>`<form data-form="rh-review"><div class="checkbox-grid">${['Motif suffisamment justifié','Description du poste disponible','Compétences requises renseignées','Données nécessaires présentes'].map((c,i)=>`<label class="checkline"><input type="checkbox" name="check${i}" ${r.rhChecks?.[i]?'checked':''}>${E(c)}</label>`).join('')}</div><div class="form-grid" style="margin-top:17px">${formField('min','Budget minimum RH (Ar)','number',r.min??'',{min:0})}${formField('max','Budget maximum RH (Ar)','number',r.max??'',{min:0})}${formField('financeRequired','L’avis Finance est-il requis ?','select',r.financeRequired?'true':'false',{options:[['true','Oui'],['false','Non']]})}${formField('decision','Avis RH','select','APPROUVER',{options:[['APPROUVER','Avis favorable / transmettre'],['RETOUR','Retour pour complément'],['REFUSER','Refuser']]})}${formField('comment','Commentaire RH','textarea','',{full:true})}</div><div class="form-actions"><button class="btn btn-primary">Enregistrer l’avis RH</button></div></form>`})}
function financeReviewScreen(){return queuePage({screen:'finance-review',status:'ATTENTE_FINANCE',title:'Avis Finance',sub:'Avis oui/non uniquement : Finance ne modifie pas le budget.',form:r=>`<form data-form="finance-review"><div class="notice">Budget RH : <b>${E(money(r.min))}</b> à <b>${E(money(r.max))}</b></div><div class="form-grid">${formField('decision','Avis de poursuite','select','OUI',{options:[['OUI','Oui, poursuivre'],['NON','Non, clôturer'],['RETOUR','Retourner pour complément']]})}${formField('comment','Motif / commentaire','textarea','',{full:true})}</div><div class="form-actions"><button class="btn btn-primary">Enregistrer l’avis Finance</button></div></form>`})}
function directionReviewScreen(){return queuePage({screen:'direction-review',status:'ATTENTE_DIRECTION',title:'Décisions de la Direction',sub:'Dernière validation des demandes avant création d’un poste.',form:r=>`<form data-form="direction-review"><div class="notice">Le dossier a franchi les étapes préalables. La Direction approuve ou refuse la demande de personnel.</div><div class="form-grid">${formField('decision','Décision finale','select','APPROUVER',{options:[['APPROUVER','Approuver'],['REFUSER','Refuser']]})}${formField('comment','Commentaire et motif de refus','textarea','',{full:true})}</div><div class="form-actions"><button class="btn btn-primary">Confirmer la décision</button></div></form>`})}
function positionsScreen(){let r=find('requests',ui.ctx.id);const ready=db.requests.filter(q=>q.status==='APPROUVEE'&&!db.positions.some(p=>p.requestId===q.id));let form=r&&ready.some(q=>q.id===r.id)&&['rh','admin'].includes(session.role)?panel('Créer un poste à partir de D-'+r.id,`<form data-form="position"><div class="form-grid">${formField('title','Intitulé','text',r.jobTitle,{required:true})}${formField('dept','Département','select',r.dept,{options:optList('departments')})}${formField('description','Description','textarea',r.description||'',{full:true})}${formField('skills','Compétences requises','textarea',r.skills||'',{full:true})}</div><div class="form-actions"><button class="btn btn-primary">Créer et associer le poste</button></div></form>`):'';let rows=db.positions.map(p=>({cols:[`P-${p.id}`,E(p.title),E(dept(p.dept)),p.requestId?'D-'+p.requestId:'Référentiel',badge(p.active?'ACTIF':'INACTIF'),db.assignments.some(a=>a.positionId===p.id&&!a.end)?badge('OCCUPE'):'Libre']}));return page('Postes associés','Un poste est distinct de l’employé qui l’occupe.', '',panel('Postes référencés',dataTable(['ID','Intitulé','Département','Demande liée','État','Occupation'],rows))+(['rh','admin'].includes(session.role)?panel('Demandes approuvées sans poste',ready.length?`<div class="action-row">${ready.map(q=>navButton('positions','Créer le poste de D-'+q.id,'secondary',q.id)).join('')}</div>`:`<p class="muted">Toutes les demandes approuvées possèdent un poste associé.</p>`):'')+form,'BLOC 1')}
function historyPanel(module,entity=null,id=null){let list=db.log.filter(x=>x.module===module&&(!entity||x.entity===entity)&&(!id||x.entityId===Number(id)));return panel('Historique des actions',list.length?`<div class="timeline">${list.map(x=>`<div class="timeline-item"><b class="small">${E(x.action.replaceAll('_',' '))}</b> ${x.after?badge(x.after):''}<div class="date">${datetime(x.date)} • ${E(x.by)}</div>${x.comment?`<p class="small muted">${E(x.comment)}</p>`:''}<div class="small muted">${E(x.entity)} #${x.entityId} ${x.before?' • '+E(x.before):''}</div></div>`).join('')}</div>`:'<div class="empty">Aucune action enregistrée pour ce dossier.</div>')}
function logScreen(module,title){let logRows=db.log.filter(l=>l.module===module).map(l=>({search:[l.action,l.by,l.entity,l.comment].join(' '),cols:[datetime(l.date),E(l.by),E(l.entity)+' #'+l.entityId,E(l.action.replaceAll('_',' ')),E(l.before||'—'),E(l.after||'—'),E(l.comment||'—')]}));return page(title,'Journal consultable, non modifiable depuis l’interface.', '',panel('Traçabilité',filters([],'Auteur, objet, action…')+dataTable(['Date','Auteur','Objet','Action','Ancienne valeur','Nouvelle valeur','Commentaire'],logRows)),module.replaceAll('_',' · '))}
function offersScreen(){let rows=db.offers.map(o=>({status:o.status,search:o.title+' '+o.id,cols:[`O-${o.id}`,`<b>${E(o.title)}</b><div class="subline">Demande D-${o.requestId}</div>`,date(o.published),date(o.close),badge(o.status),db.applications.filter(a=>a.offerId===o.id).length,`<div class="table-actions">${smallNav('offer-form',o.id,'Fiche')}${o.status==='BROUILLON'?actButton('publish-offer','Publier','success',o.id,'class="btn btn-success btn-sm"'):''}${o.status==='PUBLIEE'?actButton('close-offer','Clôturer','danger',o.id,'class="btn btn-danger btn-sm"'):''}</div>`]}));return page('Offres d’emploi','Suivi des offres rattachées à une demande approuvée.',navButton('offer-form','＋ Nouvelle offre','primary'),panel('Offres du recrutement',filters(['BROUILLON','PUBLIEE','CLOTUREE'],'Titre ou référence…')+dataTable(['Réf.','Offre','Publication','Clôture','Statut','Candidatures','Actions'],rows)),'BLOC 2 · RECRUTEMENT')}
function offerForm(){let o=find('offers',ui.ctx.id);let requests=db.requests.filter(r=>r.status==='APPROUVEE'&&db.positions.some(p=>p.requestId===r.id));let locked=o&&o.status!=='BROUILLON';return page(o?'Fiche offre O-'+o.id:'Nouvelle offre','La publication ne peut suivre qu’une demande approuvée, avec poste associé.',navButton('offers','← Offres'),panel('Informations de l’offre',`${locked?`<div class="notice warn">L’offre est ${E(displayStatus[o.status].toLowerCase())}. Ses champs sont en lecture seule dans cette V1.</div>`:''}<form data-form="offer"><div class="form-grid">${formField('requestId','Demande approuvée','select',o?.requestId||requests[0]?.id||'',{required:true,options:[['','Sélectionner une demande'],...requests.map(r=>[r.id,'D-'+r.id+' · '+r.jobTitle])]})}${formField('title','Titre de l’offre','text',o?.title||'',{required:true})}${formField('description','Description','textarea',o?.description||'',{full:true})}${formField('close','Date de clôture','date',o?.close||'')}${o?formField('status','Statut','text',displayStatus[o.status],{readonly:true}):''}${o?formField('published','Date de publication','text',o.published||'Non publiée',{readonly:true}):''}</div>${!locked?`<div class="form-actions"><button class="btn btn-primary" type="submit">Enregistrer le brouillon</button>${o?actButton('publish-offer','Publier','success',o.id):''}</div>`:''}</form>`,''), 'BLOC 2')}
function candidatesScreen(){let rows=db.candidates.map(c=>({search:JSON.stringify(c),cols:[`C-${c.id}`,`<b>${E(candidateName(c.id))}</b>`,E(c.email||'—'),E(c.phone||'—'),date(c.created),db.applications.filter(a=>a.candidateId===c.id).length,smallNav('candidate-detail',c.id,'Voir fiche')]}));return page('Répertoire des candidats','Une fiche candidat peut être reliée à plusieurs candidatures.',navButton('candidate-detail','＋ Nouveau candidat','primary'),panel('Candidats enregistrés',filters([],'Nom, prénom, email…')+dataTable(['Réf.','Nom complet','Email','Téléphone','Création','Candidatures','Actions'],rows)), 'BLOC 2')}
