function requireComment(decision,comment){return ['REFUSER','RETOUR','NON','REFUSEE_CANDIDAT','REFUSEE_DIRECTION'].includes(decision)&&!String(comment||'').trim()}
function updateRequestDecision(r,status,action,comment){transition(r,status,'BLOC_1','DEMANDE',action,comment);toast('Décision enregistrée (démonstration).')}
function ensureRange(start,end,maxMonths){if(!start)return 'Date de début obligatoire.';if(end&&end<start)return 'La date de fin précède le début.';if(maxMonths!==null&&maxMonths!==undefined){if(!end)return 'Date de fin obligatoire pour ce type de contrat.';let dateStart=new Date(start+'T12:00'),limit=new Date(dateStart);limit.setMonth(limit.getMonth()+Number(maxMonths));if(new Date(end+'T12:00')>=limit)return 'La durée excède la limite configurée de '+maxMonths+' mois.'}return ''}
function validateContract(employeeId,type,start,end,exceptId=null){let param=db.params.find(x=>x.code===type);if(!param)return 'Type de contrat inconnu.';let err=ensureRange(start,end,param.maxMonths);if(err)return err;let clashes=db.contracts.filter(c=>c.employeeId===Number(employeeId)&&c.id!==Number(exceptId)&&c.status!=='ANNULE').some(c=>{let a=end||'9999-12-31',b=c.end||'9999-12-31';return start<=b&&c.start<=a});return clashes?'Un autre contrat non annulé du salarié chevauche cette période.':''}
function validateRenewal(c,newEnd){let p=db.params.find(x=>x.code===c.type);if(!c.end)return 'Le contrat initial doit avoir une date de fin.';if(c.type==='CDI'||!p||p.maxRenew<1)return 'Le type de contrat ne permet pas le renouvellement.';if(c.previousId||db.contracts.some(x=>x.previousId===c.id))return 'Un contrat déjà renouvelé ou issu d’un renouvellement ne peut pas l’être à nouveau (V1).';let s=addDay(c.end,1);let err=ensureRange(s,newEnd,p.maxMonths);if(err)return err;let original=new Date(c.start+'T12:00'),limit=new Date(original);limit.setMonth(limit.getMonth()+Number(p.maxMonths));if(new Date(newEnd+'T12:00')>=limit)return 'La durée totale avec renouvellement dépasse le maximum paramétré.';return validateContract(c.employeeId,c.type,s,newEnd)}
function saveForm(form){let name=form.dataset.form,fd=new FormData(form),v=k=>String(fd.get(k)||'').trim(),num=k=>v(k)===''?null:Number(v(k)),id=ui.ctx.id;
 try{
  if(name==='login'){if(v('login')!=='demo'||v('password')!=='demo')throw Error('Identifiant ou mot de passe de démonstration incorrect. Utilisez demo / demo.');session={role:v('role')};sessionStorage.setItem('novarh_session',JSON.stringify(session));nav('dashboard');toast('Session de démonstration ouverte.');return}
  if(name==='request'){if(!needRole('manager'))return;if(num('min')!==null&&num('max')!==null&&num('max')<num('min'))throw Error('Le budget maximum doit être supérieur ou égal au minimum.');let r=find('requests',id);if(r&&!['BROUILLON','A_CORRIGER'].includes(r.status))throw Error('Demande non modifiable dans cet état.');if(r)Object.assign(r,{dept:num('dept'),jobTitle:v('jobTitle'),motif:v('motif'),description:v('description'),skills:v('skills'),min:num('min'),max:num('max')});else{r={id:uid('requests'),dept:num('dept'),jobTitle:v('jobTitle'),motif:v('motif'),description:v('description'),skills:v('skills'),min:num('min'),max:num('max'),author:1,created:TODAY(),status:'BROUILLON',financeRequired:false};db.requests.push(r)}log('BLOC_1','DEMANDE',r.id,'DEMANDE_ENREGISTREE','','BROUILLON');save();nav('request-check',r.id);toast('Brouillon enregistré localement.');return}
  if(name==='hierarchy'){if(!needRole('responsable'))return;let r=find('requests',id);if(r?.status!=='ATTENTE_HIERARCHIE')throw Error('Demande non disponible pour cet examen.');let dec=v('decision'),comment=v('comment');if(requireComment(dec,comment))throw Error('Un commentaire est obligatoire pour un refus ou un retour.');updateRequestDecision(r,dec==='APPROUVER'?'ATTENTE_RH':dec==='RETOUR'?'A_CORRIGER':'REFUSEE','DECISION_HIERARCHIQUE',comment);nav('hierarchy');return}
  if(name==='rh-review'){if(!needRole('rh'))return;let r=find('requests',id);if(r?.status!=='ATTENTE_RH')throw Error('Analyse RH non autorisée.');let dec=v('decision'),comment=v('comment');if(requireComment(dec,comment))throw Error('Veuillez saisir le motif.');if(num('min')!==null&&num('max')!==null&&num('max')<num('min'))throw Error('Budget maximum inférieur au minimum.');r.min=num('min');r.max=num('max');r.financeRequired=v('financeRequired')==='true';r.rhChecks=[0,1,2,3].map(i=>fd.has('check'+i));if(dec==='APPROUVER'&&r.rhChecks.some(x=>!x))throw Error('Tous les contrôles RH doivent être cochés pour transmettre.');updateRequestDecision(r,dec==='APPROUVER'?(r.financeRequired?'ATTENTE_FINANCE':'ATTENTE_DIRECTION'):dec==='RETOUR'?'A_CORRIGER':'REFUSEE','ANALYSE_RH',comment);nav('rh-review');return}
  if(name==='finance-review'){if(!needRole('finance'))return;let r=find('requests',id);if(r?.status!=='ATTENTE_FINANCE')throw Error('Avis Finance non attendu.');let dec=v('decision'),comment=v('comment');if(requireComment(dec,comment))throw Error('Le refus ou le retour demande un motif.');updateRequestDecision(r,dec==='OUI'?'ATTENTE_DIRECTION':dec==='RETOUR'?'A_CORRIGER':'REFUSEE','AVIS_FINANCE_'+dec,comment);nav('finance-review');return}
  if(name==='direction-review'){if(!needRole('direction'))return;let r=find('requests',id);if(r?.status!=='ATTENTE_DIRECTION')throw Error('Dossier indisponible pour la Direction.');let dec=v('decision'),comment=v('comment');if(requireComment(dec,comment))throw Error('Motif obligatoire pour un refus.');updateRequestDecision(r,dec==='APPROUVER'?'APPROUVEE':'REFUSEE','DECISION_DIRECTION',comment);nav('direction-review');return}
  if(name==='position'){if(!needRole('rh','admin'))return;let r=find('requests',id);if(!r||r.status!=='APPROUVEE'||db.positions.some(p=>p.requestId===r.id))throw Error('Demande non approuvée ou poste déjà créé.');let p={id:uid('positions'),requestId:r.id,title:v('title'),dept:num('dept'),description:v('description'),skills:v('skills'),active:true};db.positions.push(p);log('BLOC_1','DEMANDE',r.id,'POSTE_ASSOCIE','','P-'+p.id);save();nav('positions');toast('Poste associé à la demande.');return}
  if(name==='offer'){if(!needRole('rh'))return;let o=find('offers',id),r=find('requests',num('requestId'));if(!r||r.status!=='APPROUVEE'||!db.positions.some(p=>p.requestId===r.id))throw Error('Sélectionnez une demande approuvée possédant un poste.');if(o&&o.status!=='BROUILLON')throw Error('Seul un brouillon est modifiable.');if(v('close')&&v('close')<TODAY())throw Error('La clôture ne peut être antérieure à aujourd’hui.');if(o)Object.assign(o,{requestId:r.id,title:v('title'),description:v('description'),close:v('close')});else{o={id:uid('offers'),requestId:r.id,title:v('title'),description:v('description'),published:null,close:v('close'),status:'BROUILLON'};db.offers.push(o)}log('BLOC_2','OFFRE',o.id,'OFFRE_ENREGISTREE','','BROUILLON');save();nav('offer-form',o.id);toast('Brouillon d’offre enregistré.');return}
  if(name==='candidate'){if(!needRole('rh'))return;let c=find('candidates',id);let duplicate=db.candidates.find(x=>x.email?.toLowerCase()===v('email').toLowerCase()&&x.id!==c?.id);if(duplicate)throw Error('Un candidat possède déjà cet email.');if(c)Object.assign(c,{nom:v('nom'),prenom:v('prenom'),email:v('email'),phone:v('phone'),cv:v('cv')});else{c={id:uid('candidates'),nom:v('nom'),prenom:v('prenom'),email:v('email'),phone:v('phone'),cv:v('cv'),created:TODAY()};db.candidates.push(c)}log('BLOC_2','CANDIDAT',c.id,'FICHE_CANDIDAT_ENREGISTREE','','');save();nav('candidate-detail',c.id);toast('Candidat enregistré.');return}
  if(name==='application'){if(!needRole('rh'))return;let c=find('candidates',num('candidateId')),o=find('offers',num('offerId'));if(!c||!o||o.status!=='PUBLIEE')throw Error('Sélectionnez un candidat et une offre publiée.');if(o.close&&o.close<TODAY())throw Error('Cette offre est arrivée à échéance.');if(db.applications.some(x=>x.candidateId===c.id&&x.offerId===o.id))throw Error('Ce candidat a déjà une candidature pour cette offre.');let a={id:uid('applications'),candidateId:c.id,offerId:o.id,date:TODAY(),letter:v('letter'),status:'EN_ATTENTE'};db.applications.push(a);log('BLOC_2','CANDIDATURE',a.id,'CANDIDATURE_RECUE','','EN_ATTENTE');save();nav('preselection',a.id);toast('Candidature enregistrée.');return}
  if(name==='interview'){if(!needRole('rh'))return;let existing=find('interviews',ui.editInterview),a=find('applications',num('appId'));if(!existing&&a?.status!=='PRESELECTIONNEE')throw Error('La candidature doit être présélectionnée.');if(existing&&existing.appId!==num('appId'))throw Error('La candidature associée à l’entretien ne peut être modifiée.');let participants=v('participants')==='1'?[1,3]:[3];if(existing){Object.assign(existing,{date:v('date'),type:v('type'),location:v('location'),participants});log('BLOC_2','ENTRETIEN',existing.id,'PLANIFICATION_MODIFIEE','','PLANIFIE')}else{let i={id:uid('interviews'),appId:a.id,date:v('date'),type:v('type'),location:v('location'),status:'PLANIFIE',notes:'',participants};db.interviews.push(i);transition(a,'EN_ENTRETIEN','BLOC_2','CANDIDATURE','ENTRETIEN_PLANIFIE');log('BLOC_2','ENTRETIEN',i.id,'ENTRETIEN_PLANIFIE','','PLANIFIE')}save();nav('interviews');toast(existing?'Entretien modifié.':'Entretien planifié.');return}
  if(name==='evaluation'){if(!needRole('rh','manager'))return;let i=find('interviews',num('interviewId'));let evaluator=session.role==='manager'?1:3;if(i?.status!=='REALISE'||!i.participants.includes(evaluator))throw Error('Évaluation réservée à un entretien réalisé et attribué à ce profil.');if(db.evaluations.some(x=>x.interviewId===i.id&&x.evaluatorId===evaluator))throw Error('Vous avez déjà évalué cet entretien.');let ev={id:uid('evaluations'),interviewId:i.id,evaluatorId:evaluator,note:Number(v('note')),comment:v('comment'),decision:v('decision'),date:TODAY()};if(ev.note<0||ev.note>20)throw Error('La note doit être entre 0 et 20.');db.evaluations.push(ev);log('BLOC_2','ENTRETIEN',i.id,'EVALUATION_SAISIE','','EV-'+ev.id);save();nav('evaluations',i.id);toast('Avis enregistré.');return}
  if(name==='proposal'){if(!needRole('rh'))return;let a=find('applications',id);if(a?.status!=='RETENUE')throw Error('Candidature non retenue.');let p=db.proposals.find(x=>x.appId===a.id);if(p&&p.status!=='A_PROPOSER')throw Error('Proposition déjà envoyée.');let pos=find('positions',num('positionId'));if(!pos||find('offers',a.offerId)?.requestId!==pos.requestId)throw Error('Poste non associé au recrutement du candidat.');if(p)Object.assign(p,{positionId:pos.id,contractType:v('contractType'),salary:Number(v('salary')),start:v('start'),terms:v('terms')});else{p={id:uid('proposals'),appId:a.id,positionId:pos.id,contractType:v('contractType'),salary:Number(v('salary')),start:v('start'),terms:v('terms'),status:'A_PROPOSER',candidateResponse:null,directionDecision:null,employeeId:null,comment:'',sent:null};db.proposals.push(p)}log('BLOC_3','EMBAUCHE',p.id,'PROPOSITION_PREPAREE','','A_PROPOSER');save();nav('proposal-form',a.id);toast('Proposition enregistrée localement.');return}
  if(name==='response'){if(!needRole('rh'))return;let p=find('proposals',id);if(p?.status!=='EN_ATTENTE_REPONSE')throw Error('Proposition non en attente de réponse.');let dec=v('decision');if(requireComment(dec,v('comment')))throw Error('Un motif est obligatoire pour le refus du candidat.');p.candidateResponse=dec;p.responseDate=v('date');p.comment=v('comment');transition(p,dec==='ACCEPTEE'?'ATTENTE_DIRECTION':'REFUSEE_CANDIDAT','BLOC_3','EMBAUCHE','REPONSE_CANDIDAT',v('comment'));nav('responses');toast('Réponse saisie par RH.');return}
  if(name==='hire-validation'){if(!needRole('direction'))return;let p=find('proposals',id);if(p?.status!=='ATTENTE_DIRECTION'||p.candidateResponse!=='ACCEPTEE')throw Error('L’accord du candidat est préalable à la décision Direction.');let dec=v('decision');if(requireComment(dec,v('comment')))throw Error('Un motif est obligatoire pour le refus.');p.directionDecision=dec==='APPROUVER'?'APPROUVEE':'REFUSEE';p.decisionDate=TODAY();transition(p,dec==='APPROUVER'?'VALIDEE':'REFUSEE_DIRECTION','BLOC_3','EMBAUCHE','VALIDATION_DIRECTION',v('comment'));nav('hire-validations');toast('Décision de la Direction enregistrée.');return}
  if(name==='employee'){if(!needRole('rh'))return;let p=find('proposals',id);if(p?.status!=='VALIDEE'||p.candidateResponse!=='ACCEPTEE'||p.directionDecision!=='APPROUVEE'||p.employeeId)throw Error('Création salarié non autorisée ou déjà effectuée.');let matricule='EMP-'+String(uid('employees')).padStart(4,'0');if(db.employees.some(e=>e.matricule===matricule))throw Error('Matricule déjà utilisé.');let e={id:uid('employees'),appId:p.appId,matricule,nom:v('nom'),prenom:v('prenom'),birth:v('birth'),email:v('email'),phone:v('phone'),hired:v('hired')};db.employees.push(e);p.employeeId=e.id;transition(p,'SALARIE_CREE','BLOC_3','EMBAUCHE','DOSSIER_SALARIE_CREE');nav('assignment-b3',e.id);toast('Dossier salarié créé.');return}
  if(name==='assignment'){if(!needRole('rh'))return;let e=find('employees',id),pos=find('positions',num('positionId'));if(!e||!pos)throw Error('Salarié ou poste introuvable.');if(!freePositions(e.id).some(p=>p.id===pos.id))throw Error('Le poste sélectionné est déjà occupé.');if(ui.screen==='assignment-b3'){let p=db.proposals.find(p=>p.employeeId===e.id);if(p?.positionId!==pos.id)throw Error('L’affectation initiale doit correspondre au poste de la proposition.')}let current=activeAssignment(e.id);if(current){if(!v('end')||v('end')>=v('start')||v('end')<current.start)throw Error('Fin de l’affectation précédente invalide.');current.end=v('end')}let a={id:uid('assignments'),employeeId:e.id,positionId:pos.id,managerId:num('managerId'),start:v('start'),end:null};db.assignments.push(a);log(ui.screen==='assignment-b3'?'BLOC_3':'BLOC_4','AFFECTATION',a.id,'AFFECTATION_ENREGISTREE',current?posName(current.positionId):'Sans poste',posName(a.positionId));save();nav(ui.screen,e.id);toast('Affectation mise à jour.');return}
  if(name==='contract'){if(!needRole('rh'))return;let c=find('contracts',id),emp=num('employeeId');if(c&&c.status!=='BROUILLON')throw Error('Le contrat n’est plus modifiable.');if(!find('employees',emp))throw Error('Sélectionnez un salarié.');let eligible=db.proposals.find(p=>p.employeeId===emp);if(eligible&&eligible.status!=='TRANSMISE')throw Error('Le salarié doit être transmis au Bloc 4 avant création du contrat.');let end=v('type')==='CDI'?null:v('end');let err=validateContract(emp,v('type'),v('start'),end,c?.id);if(err)throw Error(err);if(c)Object.assign(c,{employeeId:emp,type:v('type'),start:v('start'),end,signed:v('signed')||null});else{c={id:uid('contracts'),employeeId:emp,type:v('type'),start:v('start'),end,signed:v('signed')||null,status:'BROUILLON',previousId:null};db.contracts.push(c)}log('BLOC_4','CONTRAT',c.id,'CONTRAT_BROUILLON','','BROUILLON');save();nav('contract-detail',c.id);toast('Brouillon de contrat enregistré.');return}
  if(name==='renewal'){if(!needRole('rh'))return;let c=find('contracts',id),err=validateRenewal(c,v('end'));if(err)throw Error(err);let n={id:uid('contracts'),employeeId:c.employeeId,type:c.type,start:addDay(c.end,1),end:v('end'),signed:v('signed')||null,status:'BROUILLON',previousId:c.id};db.contracts.push(n);log('BLOC_4','CONTRAT',n.id,'RENOUVELLEMENT_CREE','CT-'+c.id,'BROUILLON');save();nav('contract-detail',n.id);toast('Contrat renouvelé avec référence au précédent.');return}
  if(name==='onboarding'){if(!needRole('rh','manager'))return;let o=find('onboardings',id);if(!o)throw Error('Onboarding introuvable.');if(session.role==='manager'&&!db.assignments.some(a=>a.employeeId===o.employeeId&&a.managerId===1&&!a.end))throw Error('Hors de votre périmètre.');o.tasks.forEach((t,i)=>{let status=v('status'+i);if(!['A_FAIRE','EN_COURS','TERMINE'].includes(status))throw Error('Statut de tâche invalide.');if(i===0&&status!=='TERMINE')throw Error('La tâche « Contrat signé » reste terminée après signature.');t.status=status;t.responsible=v('responsible'+i);t.due=v('due'+i)||null;t.completed=status==='TERMINE'?(v('completed'+i)||TODAY()):null});log('BLOC_4','ONBOARDING',o.id,'TACHES_MISES_A_JOUR','',''+onboardingState(o));save();nav('onboarding-detail',o.id);toast('Suivi des six tâches mis à jour.');return}
  if(name==='settings'){if(!needRole('admin'))return;db.params.forEach((p,i)=>{if(!v('name'+i))throw Error('Libellé obligatoire.');let m=p.code==='CDI'?null:Number(v('months'+i)),renew=Number(v('renew'+i));if(p.code!=='CDI'&&(!(m>0)||!Number.isInteger(m)))throw Error('La durée doit être positive.');if(renew<0||!Number.isInteger(renew))throw Error('Le nombre de renouvellements est invalide.');p.name=v('name'+i);p.maxMonths=m;p.maxRenew=renew});save();render();toast('Paramètres mis à jour.');return}
  if(name==='user'){if(!needRole('admin'))return;if(!PROFILES[v('role')])throw Error('Rôle invalide.');db.users.push({id:uid('users'),name:v('name'),role:v('role'),dept:num('dept')});save();render();toast('Utilisateur ajouté à la démonstration.');return}
  if(name==='user-edit'){if(!needRole('admin'))return;let u=find('users',id);if(!u)throw Error('Utilisateur introuvable.');u.name=v('name');u.role=v('role');u.dept=num('dept');save();nav('users');toast('Utilisateur modifié localement.');return}
  if(name==='department'){if(!needRole('admin'))return;if(db.departments.some(x=>x.name.toLowerCase()===v('name').toLowerCase()))throw Error('Département déjà présent.');db.departments.push({id:uid('departments'),name:v('name')});save();render();toast('Département ajouté.');return}
  if(name==='document'){if(!needRole('rh'))return;let f=fd.get('file'),employeeId=num('employeeId'),contractId=num('contractId');if(!f||!f.size)throw Error('Choisissez un fichier.');if(f.size>700*1024)throw Error('Fichier trop volumineux pour le stockage local de démonstration (700 Ko).');if(!['application/pdf','image/png','image/jpeg','image/webp','text/plain'].includes(f.type))throw Error('Type de fichier non pris en charge dans cette démo.');if(contractId&&find('contracts',contractId)?.employeeId!==employeeId)throw Error('Le contrat sélectionné appartient à un autre salarié.');let reader=new FileReader();reader.onload=()=>{let d={id:uid('docs'),employeeId,contractId:contractId||null,type:v('type'),name:f.name,size:f.size,mime:f.type,date:TODAY(),data:reader.result};db.docs.push(d);log('BLOC_4','DOCUMENT',d.id,'DOCUMENT_AJOUTE','','',f.name);save();nav('documents');toast('Fichier enregistré uniquement dans ce navigateur.')};reader.onerror=()=>toast('Lecture du fichier impossible.','error');reader.readAsDataURL(f);return}
  throw Error('Formulaire non reconnu : '+name)
 }catch(e){toast(e.message||'Impossible de traiter le formulaire','error')}
}
function runAction(action,id){let x;
 switch(action){
 case 'collapse':ui.collapsed=!ui.collapsed;render();return;
 case 'mobile-toggle':ui.mobile=!ui.mobile;render();return;
 case 'mobile-close':ui.mobile=false;render();return;
 case 'logout':session=null;sessionStorage.removeItem('novarh_session');ui.screen='dashboard';render();return;
 case 'toggle-password':{let el=document.getElementById('login-pass');if(el)el.type=el.type==='password'?'text':'password';return}
 case 'close-modal':ui.modal=null;renderModal();return;
 case 'modal-confirm':{let f=ui.modal?.callback,c=document.getElementById('modal-comment')?.value.trim()||'';ui.modal=null;renderModal();if(f){try{f(c)}catch(err){toast(err.message,'error')}}return}
 case 'reset':ask('Réinitialiser la démonstration','Toutes les modifications enregistrées dans ce navigateur seront perdues. Les données de départ seront restaurées.',()=>{db=SEED();save();nav('dashboard');toast('Données de démonstration restaurées.')},true);return;
 case 'request-submit':if(!needRole('manager'))return;x=find('requests',id);if(!x||!['BROUILLON','A_CORRIGER'].includes(x.status))return toast('Demande indisponible.','error');if(!x.jobTitle||!x.motif)return toast('Compléter le poste et le motif.','error');ask('Soumettre la demande','La demande sera transmise au responsable hiérarchique. Vous ne pourrez plus la modifier sauf retour.',comment=>{transition(x,'ATTENTE_HIERARCHIE','BLOC_1','DEMANDE','DEMANDE_SOUMISE',comment);nav('request-check',x.id);toast('Demande soumise au responsable.')});return;
 case 'publish-offer':if(!needRole('rh'))return;x=find('offers',id);if(!x||x.status!=='BROUILLON')return toast('Offre non publiable.','error');if(!x.title||!x.description||!find('requests',x.requestId)||find('requests',x.requestId).status!=='APPROUVEE'||!db.positions.some(p=>p.requestId===x.requestId))return toast('Titre, description et demande approuvée avec poste sont nécessaires.','error');if(x.close&&x.close<TODAY())return toast('Date de clôture déjà passée.','error');ask('Publier cette offre','La publication est enregistrée dans le prototype. Aucun site d’emploi externe n’est contacté.',comment=>{x.published=TODAY();transition(x,'PUBLIEE','BLOC_2','OFFRE','OFFRE_PUBLIEE',comment);nav('offers');toast('Offre publiée dans la démonstration.')});return;
 case 'close-offer':if(!needRole('rh'))return;x=find('offers',id);if(x?.status!=='PUBLIEE')return toast('Offre non publiée.','error');ask('Clôturer l’offre','Plus aucune nouvelle candidature ne pourra être créée pour cette offre. Les candidatures existantes restent consultables.',comment=>{transition(x,'CLOTUREE','BLOC_2','OFFRE','OFFRE_CLOTUREE',comment);nav('offers')},true);return;
 case 'preselect':if(!needRole('rh'))return;x=find('applications',id);if(x?.status!=='EN_ATTENTE')return toast('Présélection impossible.','error');transition(x,'PRESELECTIONNEE','BLOC_2','CANDIDATURE','CANDIDATURE_PRESELECTIONNEE');nav('preselection',id);toast('Candidature présélectionnée.');return;
 case 'reject-application':if(!needRole('rh'))return;x=find('applications',id);if(!x||!['EN_ATTENTE','PRESELECTIONNEE','EN_ENTRETIEN'].includes(x.status))return toast('Rejet impossible dans cet état.','error');ask('Rejeter la candidature','Un motif est obligatoire et sera conservé dans l’historique.',comment=>{if(!comment)throw Error('Indiquez obligatoirement le motif du rejet.');transition(x,'REJETEE','BLOC_2','CANDIDATURE','CANDIDATURE_REJETEE',comment);nav('preselection',id)},true);return;
 case 'edit-interview':if(!needRole('rh'))return;x=find('interviews',id);if(x?.status!=='PLANIFIE')return toast('Seuls les entretiens planifiés sont modifiables.','error');ui.screen='interviews';ui.editInterview=Number(id);render();window.scrollTo(0,0);return;
 case 'interview-done':if(!needRole('rh'))return;x=find('interviews',id);if(x?.status!=='PLANIFIE')return toast('Entretien non planifié.','error');ask('Marquer l’entretien réalisé','Saisissez un compte rendu succinct avant de terminer.',comment=>{if(!comment)throw Error('Un compte rendu est nécessaire.');x.notes=comment;transition(x,'REALISE','BLOC_2','ENTRETIEN','ENTRETIEN_REALISE',comment);nav('interviews')});return;
 case 'interview-cancel':if(!needRole('rh'))return;x=find('interviews',id);if(x?.status!=='PLANIFIE')return toast('Entretien non planifié.','error');ask('Annuler l’entretien','Le rendez-vous sera marqué annulé, sans effacer la candidature.',comment=>{if(!comment)throw Error('Précisez le motif d’annulation.');transition(x,'ANNULE','BLOC_2','ENTRETIEN','ENTRETIEN_ANNULE',comment);nav('interviews')},true);return;
 case 'retain-application':if(!needRole('rh'))return;x=find('applications',id);if(x?.status!=='EN_ENTRETIEN')return toast('Candidature non éligible.','error');if(!db.evaluations.some(ev=>db.interviews.some(i=>i.id===ev.interviewId&&i.appId===x.id&&i.status==='REALISE')))return toast('Il faut au moins une évaluation d’entretien réalisé.','error');ask('Retenir le candidat','La candidature passera au Bloc 3. Le candidat ne devient pas encore salarié.',comment=>{transition(x,'RETENUE','BLOC_2','CANDIDATURE','DECISION_FINALE',comment);nav('proposal-form',x.id)});return;
 case 'send-proposal':if(!needRole('rh'))return;x=find('proposals',id);if(x?.status!=='A_PROPOSER')return toast('Proposition non prête.','error');ask('Envoyer la proposition','Simulation d’envoi uniquement. Vous pourrez ensuite saisir la réponse reçue par RH.',comment=>{x.sent=TODAY();transition(x,'EN_ATTENTE_REPONSE','BLOC_3','EMBAUCHE','PROPOSITION_ENVOYEE',comment);nav('responses',x.id);toast('Envoi simulé, aucun email transmis.')});return;
 case 'transmit':if(!needRole('rh'))return;x=find('proposals',id);if(!x||x.status!=='SALARIE_CREE'||!x.employeeId||!activeAssignment(x.employeeId))return toast('Dossier salarié ou affectation manquants.','error');transition(x,'TRANSMISE','BLOC_3','EMBAUCHE','DOSSIER_TRANSMIS');nav('handoff');toast('Dossier transmis au Bloc 4 dans le prototype.');return;
 case 'sign-contract':if(!needRole('rh'))return;x=find('contracts',id);if(x?.status!=='BROUILLON')return toast('Contrat non signé depuis ce statut.','error');{let err=validateContract(x.employeeId,x.type,x.start,x.end,x.id);if(err)return toast(err,'error')}ask('Signer le contrat','Cette signature est une simulation d’état. Le document signé devra être ajouté dans les documents.',comment=>{x.signed=x.signed||TODAY();transition(x,'SIGNE','BLOC_4','CONTRAT','CONTRAT_SIGNE',comment);if(!db.onboardings.some(o=>o.employeeId===x.employeeId)){let o={id:uid('onboardings'),employeeId:x.employeeId,created:TODAY(),tasks:TASK_NAMES.map((name,i)=>({name,status:i===0?'TERMINE':'A_FAIRE',responsible:i===0?PROFILES.rh.name:'',due:x.start,completed:i===0?TODAY():null}))};db.onboardings.push(o);log('BLOC_4','ONBOARDING',o.id,'ONBOARDING_CREE','','6_TACHES')}save();nav('contract-detail',id);toast('Contrat signé (simulation), onboarding créé.')});return;
 case 'start-contract':if(!needRole('rh'))return;x=find('contracts',id);if(x?.status!=='SIGNE')return toast('Ce contrat n’est pas signé.','error');if(x.start>TODAY())return toast('La date de début du contrat n’est pas atteinte.','error');if(!db.docs.some(d=>d.contractId===x.id&&d.type==='Contrat signé'))return toast('Déposez d’abord le document de contrat signé.','error');transition(x,'EN_COURS','BLOC_4','CONTRAT','CONTRAT_DEMARRE');nav('contract-detail',id);return;
 case 'end-contract':if(!needRole('rh'))return;x=find('contracts',id);if(x?.status!=='EN_COURS')return toast('Contrat non en cours.','error');ask('Terminer le contrat','Fin administrative de la période contractuelle dans la démonstration.',comment=>{transition(x,'TERMINE','BLOC_4','CONTRAT','CONTRAT_TERMINE',comment);nav('contract-detail',id)},true);return;
 case 'cancel-contract':if(!needRole('rh'))return;x=find('contracts',id);if(!['BROUILLON','SIGNE'].includes(x?.status))return toast('Annulation indisponible.','error');ask('Annuler le contrat','Cette action ne supprime pas les données d’historique.',comment=>{if(!comment)throw Error('Un motif d’annulation est obligatoire.');transition(x,'ANNULE','BLOC_4','CONTRAT','CONTRAT_ANNULE',comment);nav('contract-detail',id)},true);return;
 case 'download-doc':if(!needRole('rh'))return;x=find('docs',id);if(!x?.data)return toast('Ce document fictif ne contient pas de vrai fichier.','error');{let a=document.createElement('a');a.href=x.data;a.download=x.name;document.body.append(a);a.click();a.remove();return}
 case 'edit-user':if(!needRole('admin'))return;nav('users',id);return;
 default:toast('Action non reconnue : '+action,'error');
 }
}
function setPostRender(){let sel=document.querySelector('[data-form="contract"] select[name="type"]');if(sel){let end=document.querySelector('[data-form="contract"] input[name="end"]');if(end){end.disabled=sel.value==='CDI';end.required=sel.value!=='CDI'}}}
document.addEventListener('click',event=>{const group=event.target.closest('[data-group]');if(group){let k=group.dataset.group;ui.groups[k]=ui.groups[k]===false?true:false;render();return}const n=event.target.closest('[data-nav]');if(n){nav(n.dataset.nav,n.dataset.id||'');setPostRender();return}const a=event.target.closest('[data-action]');if(a){runAction(a.dataset.action,a.dataset.id);setPostRender();return}const sort=event.target.closest('[data-sort]');if(sort){let n=Number(sort.dataset.sort);ui.sortDesc=ui.sort===n?!ui.sortDesc:false;ui.sort=n;render();return}const pagination=event.target.closest('[data-page]');if(pagination){ui.page+=pagination.dataset.page==='next'?1:-1;render();return}if(event.target.matches('[data-modal-bg]')){ui.modal=null;renderModal()}});
document.addEventListener('submit',e=>{const f=e.target.closest('form[data-form]');if(!f)return;e.preventDefault();saveForm(f);setPostRender()});
document.addEventListener('change',e=>{if(e.target.matches('[data-role]')){session.role=e.target.value;sessionStorage.setItem('novarh_session',JSON.stringify(session));nav('dashboard');toast('Profil changé. Permissions visuelles adaptées.');return}if(e.target.matches('[data-filter]')){ui.filter=e.target.value;ui.page=1;render();return}if(e.target.matches('[data-contract-type]')){ui.contractType=e.target.value;ui.page=1;render();return}if(e.target.matches('[data-form="contract"] select[name="type"]')){setPostRender()}});
document.addEventListener('input',e=>{if(!e.target.matches('[data-search]'))return;let value=e.target.value,at=e.target.selectionStart;ui.search=value;ui.page=1;render();let input=document.querySelector('[data-search]');if(input){input.focus();try{input.setSelectionRange(at,at)}catch{}}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&ui.modal){ui.modal=null;renderModal()}});
try{let hash=decodeURIComponent(location.hash.slice(1)).split('/');if(hash[0]&&menuAccess[session?.role]?.includes(hash[0])){ui.screen=hash[0];ui.ctx=hash[1]?{id:Number(hash[1])}:{}}}catch{}
render();setPostRender();
